import { readFile, writeFile } from 'node:fs/promises';
const root = new URL('../', import.meta.url);
const assignments = JSON.parse(await readFile(new URL('docs/duties/requirements.json', root), 'utf8'));
const escape = value => String(value).replaceAll('|', '\\|').replaceAll('\n', ' ');
const lines = [
  '# Full requirement implementation matrix', '',
  'Generated by `pnpm matrix:generate` from [requirements.json](duties/requirements.json). All 88 PRD requirements retain their priorities and role-based primary owners. Planned implementations are assignments, not completed features. Models remain candidates until licence, six-language/format quality, RAM and latency are measured.', '',
  'Status: `planned` = product implementation pending; `foundation_partial` = auth/access foundations only; `adapter_partial` = provider telemetry only. No requirement is marked complete by a runtime smoke test.', '',
  'Each acceptance scenario below additionally inherits the exact PRD requirement and its detailed metric targets. API spending refers to hosted AI only; compute, storage, identity, messaging, map/network use and production hosting are not assumed cost-free.', '',
];
for (const [family, label] of [['M', 'Mobile'], ['W', 'Dashboard and organisations'], ['A', 'AI pipeline']]) {
  lines.push(`## ${label}`, '', '| ID / priority | Owner | Execution | Implementation / local strategy | Dependencies | Cost exposure | Acceptance | Status |', '| --- | --- | --- | --- | --- | --- | --- | --- |');
  for (const [id, entry] of Object.entries(assignments).filter(([id]) => id.startsWith(family + '-'))) {
    lines.push(`| ${id} · ${escape(entry.priority)} | [${entry.owner.split('-').slice(0, 2).join(' ')}](duties/${entry.owner}.md) | ${escape(entry.execution)} | ${escape(entry.implementation)}. ${escape(entry.local_strategy)} | ${escape(entry.dependencies.join('; '))} | ${escape(entry.cost_exposure)} | ${escape(entry.acceptance_test)} | ${escape(entry.status)} |`);
  }
  lines.push('');
}
await writeFile(new URL('docs/implementation-matrix.md', root), lines.join('\n'));
console.log(`Generated matrix for ${Object.keys(assignments).length} requirements.`);
